import json,html
from pathlib import Path
R=Path('/tmp/cr-prof/bench-safe');a=json.loads((R/'analysis.json').read_text())
tele={r['label']:json.loads((R/(r['label']+'-telemetry.json')).read_text()) for r in a['raw_runs']}
a['memory_telemetry']=tele
payload=json.dumps(a,ensure_ascii=False).replace('</','<\\/')
page=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RL pipeline · final 8-worker benchmark</title><style>
:root{color-scheme:dark;--bg:#09141b;--panel:#13242e;--ink:#e9f3f5;--muted:#9db7c1;--grid:#29414b;--a:#f3b266;--b:#69d1c5;--c:#95a8ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 system-ui,sans-serif}main{max-width:1200px;margin:auto;padding:44px 24px 70px}h1{font-size:clamp(28px,4vw,48px);letter-spacing:-1.7px;line-height:1.1;margin:15px 0}h2{font-size:23px;margin:0 0 14px}.eyebrow{color:var(--b);text-transform:uppercase;letter-spacing:.15em;font-size:12px}.sub,p{max-width:950px;color:var(--muted)}.pill{display:inline-block;border:1px solid var(--grid);border-radius:99px;padding:4px 12px;margin:4px 4px 4px 0;font-size:12px}.cards,.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:24px 0}.card,section{background:var(--panel);border:1px solid var(--grid);border-radius:15px;padding:22px}.card b{display:block;font-size:30px;letter-spacing:-1px}.card small{color:var(--muted)}section{margin:22px 0}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}th,td{text-align:left;padding:10px 8px;border-bottom:1px solid var(--grid);font-size:13px}th{color:var(--muted);font-weight:500}tr:hover{background:#ffffff05}.scroll{overflow:auto}button,select{color:var(--ink);background:#213943;border:1px solid #3a5964;padding:7px 12px;border-radius:8px;cursor:pointer}button:hover{background:#2c4b57}label{margin-right:15px;font-size:12px;white-space:nowrap}.chart{min-height:290px;position:relative}.chart svg{width:100%;height:auto;display:block}.tip{position:fixed;pointer-events:none;background:#e9f3f5;color:#09141b;padding:8px 12px;border-radius:7px;font-size:12px;box-shadow:0 6px 30px #0008;display:none;z-index:3;white-space:pre-line}code{font-size:12px;color:#b8d7dd;overflow-wrap:anywhere}summary{cursor:pointer;color:var(--b)}.note{border-left:3px solid var(--a);padding-left:14px}.metric{color:var(--b);font-weight:700}.two{display:grid;grid-template-columns:1fr 1fr;gap:20px}.phase-row{display:grid;grid-template-columns:180px 1fr 75px;align-items:center;gap:12px;font-size:12px;margin:9px 0}.bar{height:11px;background:var(--b);border-radius:7px}.foot{font-size:12px;color:var(--muted)}@media(max-width:750px){.cards,.grid,.two{grid-template-columns:1fr}.phase-row{grid-template-columns:125px 1fr 60px}main{padding:24px 12px}.card,section{padding:16px}}
</style><main><div class="eyebrow">Native simulator · CUDA learner · resource bounded</div><h1>Faster RL collection,<br>measured at eight workers.</h1><p class="sub">Final-code comparison of the historical baseline and the optimized one-group / two-group schedulers. Six serial scratch runs, two seeds, three collect + PPO waves each. This measures throughput and reproducibility, not playing strength.</p><div><span class="pill">RTX 3060 · 8GB VRAM</span><span class="pill">13th gen Core i5 · 32GB RAM</span><span class="pill">8GiB hard trainer memory cap</span><span class="pill">zero trainer swap</span><span class="pill">No live game</span></div><div class="cards" id="cards"></div><section><h2>Decision and evidence</h2><p id="decision"></p><p class="note">The previous 12/16-worker matrix exhausted host RAM and was interrupted. Its eight completed observations predate the final correctness fix. They are retained separately below and never substitute for the final eight-worker measurements.</p><p id="identity"></p></section><section><h2>Throughput across complete training runs</h2><p>Each number includes three training waves and cleanup; constructor time is separately recorded. Ratios are paired by seed. The two-seed range describes these observations, not a confidence interval.</p><div class="scroll"><table id="rates"></table></div><div class="scroll"><table id="paired"></table></div></section><section><h2>Wave curves</h2><p>Hover a point for the exact value. Toggle any run to remove it. Wave 1 starts from the same parent policy and is shown separately because subsequent PPO updates can produce different trajectories and amounts of simulation work.</p><select id="waveMetric"><option value="games_per_min">Games / minute</option><option value="decisions_per_s">Decisions / second</option><option value="wave_s">Wave seconds</option><option value="decisions">Decisions collected</option></select> <button id="animate">Replay curve evolution</button><div id="waveToggles"></div><div class="chart" id="waveChart"></div><div class="scroll"><table id="first"></table></div></section><section><h2>Where the time remains</h2><p>Median seconds across each configuration's two runs. Encoding is nested inside <code>act_batch</code>; <code>act_batch</code> is nested inside launch. Act includes CPU work, masks, sampling, device transfers and GPU inference, so it is not pure GPU execution. Exposed wait is the wait still visible to the scheduler after overlap. These bars are separate measurements and must not be added together.</p><select id="phaseConfig"></select><div id="phases"></div><p class="foot">Residual/reset/orchestration is approximate: total − launch − exposed wait − consume − publish − PPO. Publish may also occur within an update, so small nested overlap remains. Native reset/step/mask request sums are concurrency diagnostics, not wall-time components; their latency can overlap across workers. First-wave reset also includes native process startup.</p><div class="scroll"><table id="native"></table></div></section><section><h2>Training curves from the measured runs</h2><p>Every run performs exactly three PPO updates on eight sampled games per wave (24 games/run; 144 game outcomes total). The loss, entropy and KL values below come from the trainer's actual <code>updates.jsonl</code>. They describe three short benchmark updates and do not establish convergence or model quality.</p><select id="trainMetric"><option value="loss">PPO loss</option><option value="policy_loss">Policy loss</option><option value="value_loss">Value loss</option><option value="entropy">Entropy</option><option value="approx_kl">Approximate KL</option><option value="parent_kl">Parent KL</option><option value="samples">Training samples</option></select><div id="trainToggles"></div><div class="chart" id="trainChart"></div></section><section><h2>Outcome comparison, paired by policy version + seed</h2><p>Exact means all five recorded fields match: deck, controller, seat, W/L/D result and simulated seconds. Job equality considers deck/controller/seat. An equal terminal outcome does not prove the same actions. The final implementation intentionally makes score/tile tie ordering stable and trims sampled support widths while retaining the all-uniform fast path; ties and later optimizer trajectories can change.</p><div class="scroll"><table id="outcomes"></table></div><details><summary>All per-field match counts and mismatches</summary><pre id="agreement" style="white-space:pre-wrap;font-size:11px"></pre></details></section><section><h2>Memory boundaries and run health</h2><p>Every trainer and all its native children ran in an isolated transient user service with <code>MemoryMax=8G</code>, <code>MemorySwapMax=0</code>, <code>OOMPolicy=kill</code> and whole-cgroup cleanup. A supervisor required ≥12GiB host available RAM before each launch, polled every 0.5s and would stop only its current benchmark unit below 6GiB available RAM or on a cgroup memory-cap event. No other jobs were stopped; no caches were cleared.</p><div class="scroll"><table id="memory"></table></div><p class="foot">Cgroup memory in GiB versus elapsed seconds since the full matrix began; colors identify configurations and dashed lines identify seed 2026.</p><div class="chart" id="memoryChart"></div><p class="foot">Hard caps are enforced by the kernel between samples. Peak is the maximum of cgroup memory.peak, systemd MemoryPeak and sampled current memory. This eight-worker result is the tested operating point; 16 workers are not recommended as safe from earlier speed alone.</p></section><section><h2>Method, limitations and lessons</h2><p>All runs use the same native engine binary, pool, parent checkpoint and initial state. Seed 777 order: baseline → g1 → g2. Seed 2026 reverses that order. Policies remain fixed while games within a wave are active; PPO happens between waves. Engines are local simulated games; no network, phone game, installations or long production training were needed.</p><p>Encoding, inclusive policy action work, exposed native wait, PPO and reset/orchestration remain useful optimization targets. Use decisions/second alongside games/minute because policy trajectories change game length and the number of decisions. First-wave timings are the cleanest comparison from the initial model, but first-wave native startup/reset is included.</p><p id="validation"></p><details><summary>Exact invocation commands and immutable input hashes</summary><pre id="commands" style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px"></pre></details><button id="download">Download embedded benchmark JSON</button></section><section><h2>Supplement: earlier incomplete matrix</h2><p>Historical observations only: before final correctness fix, uncapped earlier run, incomplete schedule after host OOM. Do not use these rows to claim final-code behavior or recommend these worker counts.</p><div class="scroll"><table id="old"></table></div></section><p class="foot" id="footer"></p></main><div class="tip" id="tip"></div><script id="data" type="application/json">''' + payload + r'''</script><script>
const D=JSON.parse(document.getElementById('data').textContent),N=['BASELINE8','NEW8g1','NEW8g2'],C=['#f3b266','#69d1c5','#95a8ff'],fmt=(n,d=2)=>Number(n).toFixed(d),gib=n=>n/1073741824,$=id=>document.getElementById(id),M=D.medians;
function table(id,heads,rows){$(id).innerHTML='<thead><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody>'}
const best=M.NEW8g2.decisions_per_s>M.NEW8g1.decisions_per_s?'NEW8g2':'NEW8g1',bp=D.paired_speedups.find(p=>p.a==='BASELINE8'&&p.b===best),vs=D.paired_speedups.find(p=>p.a==='NEW8g1'&&p.b==='NEW8g2');
$('cards').innerHTML=N.map((n,i)=>'<div class="card"><small style="color:'+C[i]+'">'+n+' · median</small><b>'+fmt(M[n].games_per_min)+' <small>games/min</small></b><div>'+fmt(M[n].decisions_per_s)+' decisions/s</div><small>'+fmt(gib(M[n].memory_peak_bytes))+'GiB median peak</small></div>').join('');
$('decision').innerHTML='Use <span class="metric">'+best+'</span> at eight workers as the measured throughput preference. Its median is '+fmt(M[best].games_per_min/M.BASELINE8.games_per_min)+'× baseline games/min and '+fmt(M[best].decisions_per_s/M.BASELINE8.decisions_per_s)+'× decisions/s. Paired decision speedups span '+fmt(bp.range.decisions_per_s.min)+'–'+fmt(bp.range.decisions_per_s.max)+'×. The g2/g1 decision ratios are '+vs.seeds.map(s=>s.seed+': '+fmt(s.decisions_per_s)+'×').join(', ')+'. Two seeds give limited evidence about small scheduler differences; eight workers is the memory-bounded operating point tested here.';
$('identity').innerHTML='Model: '+D.model+'. Created '+D.created_utc+'. Baseline <code>'+D.baseline_head+'</code>; final <code>'+D.final_head+'</code>.';
table('rates',['Configuration','Seed','Games','Decisions','Total s','Games/min','Decisions/s','Updates'],D.runs.map(r=>[r.configuration,r.seed,r.games,r.decisions,fmt(r.total_s),fmt(r.games_per_min),fmt(r.decisions_per_s),3]));
table('paired',['Comparison','Games/min ratio: median [range]','Decisions/s ratio: median [range]'],D.paired_speedups.map(p=>[p.b+' / '+p.a,...['games_per_min','decisions_per_s'].map(m=>fmt(p.range[m].median)+'× ['+fmt(p.range[m].min)+'–'+fmt(p.range[m].max)+']')]));
table('first',['First wave','Seed','Seconds','Games/min','Decisions/s'],D.runs.map(r=>[r.configuration,r.seed,fmt(r.first_wave_s),fmt(r.first_wave_games_per_min),fmt(r.first_wave_decisions_per_s)]));
const series=D.raw_runs.map((r,i)=>({id:r.label,name:r.configuration+' · '+r.seed,color:C[N.indexOf(r.configuration)],dash:r.seed===2026,points:r.wave_records.map(w=>({x:w.wave,...D.wave_records.find(p=>p.configuration===r.configuration&&p.seed===r.seed&&p.wave===w.wave)}))}));
function toggles(id,ss,draw){$(id).innerHTML=ss.map((s,i)=>'<label><input type="checkbox" checked data-i="'+i+'"><span style="color:'+s.color+'">'+s.name+(s.dash?' · dashed':'')+'</span></label>').join('');$(id).querySelectorAll('input').forEach(x=>x.onchange=draw)}
function chart(id,ss,metric,maxWave=Infinity,checks){let active=ss.filter((s,i)=>!checks||checks[i].checked);const all=active.flatMap(s=>s.points.filter(p=>p.x<=maxWave&&Number.isFinite(+p[metric]))),W=1050,H=320,L=60,R=24,T=25,B=45;if(!all.length){$(id).innerHTML='No visible series';return}let xmin=Math.min(...all.map(p=>p.x)),xmax=Math.max(...all.map(p=>p.x)),ymin=Math.min(0,...all.map(p=>+p[metric])),ymax=Math.max(...all.map(p=>+p[metric]));if(xmax===xmin)xmax=xmin+1;if(ymax===ymin)ymax=ymin+1;let ypad=(ymax-ymin)*.08;ymin-=ypad;ymax+=ypad;let x=v=>L+(v-xmin)/(xmax-xmin)*(W-L-R),y=v=>H-B-(v-ymin)/(ymax-ymin)*(H-T-B),s='<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+metric+' curve">';for(let i=0;i<=4;i++){let v=ymin+(ymax-ymin)*i/4;s+='<path d="M'+L+' '+y(v)+'H'+(W-R)+'" stroke="#29414b"/><text x="'+(L-9)+'" y="'+(y(v)+4)+'" fill="#9db7c1" font-size="11" text-anchor="end">'+fmt(v,Math.abs(v)<1?3:1)+'</text>'}for(let v of [...new Set(all.map(p=>p.x))].filter((v,i,arr)=>arr.length<10||i%Math.ceil(arr.length/8)===0)){s+='<text x="'+x(v)+'" y="'+(H-15)+'" fill="#9db7c1" font-size="11" text-anchor="middle">'+fmt(v,Number.isInteger(v)?0:1)+'</text>'}active.forEach(sx=>{const pp=sx.points.filter(p=>p.x<=maxWave&&Number.isFinite(+p[metric]));s+='<polyline fill="none" stroke="'+sx.color+'" stroke-width="2.3" '+(sx.dash?'stroke-dasharray="7 5"':'')+' points="'+pp.map(p=>x(p.x)+','+y(p[metric])).join(' ')+'"/>';pp.forEach(p=>{s+='<circle cx="'+x(p.x)+'" cy="'+y(p[metric])+'" r="'+(pp.length>20?2:5)+'" fill="'+sx.color+'" data-tip="'+sx.name+'|x '+fmt(p.x)+'|'+metric+': '+fmt(p[metric],4)+'"/>'})});$(id).innerHTML=s+'</svg>';$(id).querySelectorAll('[data-tip]').forEach(el=>{el.onmousemove=e=>{let t=$('tip');t.style.display='block';t.style.left=Math.min(innerWidth-250,e.clientX+12)+'px';t.style.top=e.clientY+12+'px';t.textContent=el.dataset.tip.replaceAll('|','\n')};el.onmouseleave=()=>{$('tip').style.display='none'}})}
let waveLimit=3;function drawWave(){chart('waveChart',series,$('waveMetric').value,waveLimit,$('waveToggles').querySelectorAll('input'))}toggles('waveToggles',series,drawWave);$('waveMetric').onchange=drawWave;$('animate').onclick=()=>{waveLimit=1;drawWave();let t=setInterval(()=>{waveLimit++;drawWave();if(waveLimit===3)clearInterval(t)},650)};drawWave();
const train=D.raw_runs.map(r=>({id:r.label,name:r.configuration+' · '+r.seed,color:C[N.indexOf(r.configuration)],dash:r.seed===2026,points:(D.training_curves[r.label]||[]).map(p=>({x:p.updates,...p}))}));function drawTrain(){chart('trainChart',train,$('trainMetric').value,Infinity,$('trainToggles').querySelectorAll('input'))}toggles('trainToggles',train,drawTrain);$('trainMetric').onchange=drawTrain;drawTrain();
$('phaseConfig').innerHTML=N.map(n=>'<option>'+n+'</option>').join('');function drawPhases(){let r=M[$('phaseConfig').value],items=[['Encoding · nested in act','cache_request_s'],['Act inclusive · nested in launch','act_batch_s'],['Act minus encoding','act_minus_encoding_s'],['Launch inclusive','launch_s'],['Exposed native wait','wait_steps_s'],['PPO update inclusive','update_s'],['Consume','consume_s'],['Publish','publish_s'],['Residual/reset · approximate','residual_reset_orchestration_s']],max=Math.max(...items.map(x=>r[x[1]]));$('phases').innerHTML=items.map(([n,k])=>'<div class="phase-row"><span>'+n+'</span><div class="bar" style="width:'+100*Math.max(0,r[k])/max+'%"></div><span>'+fmt(r[k])+'s</span></div>').join('')}$('phaseConfig').onchange=drawPhases;drawPhases();
table('native',['Median diagnostic sum (overlapping requests)','Reset s','Step s','Mask s'],N.map(n=>[n,...['engine_reset_sum_s','engine_step_sum_s','engine_mask_sum_s'].map(k=>fmt(M[n][k]))]));
table('outcomes',['Pair / seed','Wave','Count A/B','Paired','Jobs equal','All five exact'],D.outcome_agreement.flatMap(p=>p.per_wave.map(w=>[p.a+' → '+p.b+' / '+p.seed,w.wave,w.count_a+'/'+w.count_b,w.paired,w.jobs_equal,w.exact])));$('agreement').textContent=JSON.stringify(D.outcome_agreement,null,2);
const memory=D.raw_runs.map(r=>{let t=D.memory_telemetry[r.label];return {r,t,min:Math.min(...t.samples.map(s=>s.host.MemAvailable)),max:gib(t.peak_bytes),hits:Math.max(...t.samples.map(s=>s.memory_events?.max||0)),oom:Math.max(...t.samples.map(s=>s.memory_events?.oom_kill||0))}});table('memory',['Configuration','Seed','Peak GiB','Host minimum available GiB','Cap hits','OOM kills','Result'],memory.map(m=>[m.r.configuration,m.r.seed,fmt(m.max,3),fmt(gib(m.min),3),m.hits,m.oom,m.t.final_unit.Result]));
let ms=memory.map((m,i)=>({name:m.r.configuration+' · '+m.r.seed,color:C[N.indexOf(m.r.configuration)],dash:m.r.seed===2026,points:m.t.samples.map(s=>({x:s.elapsed_s,memory_gib:gib(s.cgroup_memory_current||+(s.unit.MemoryCurrent||0))})).filter(p=>Number.isFinite(p.memory_gib))}));chart('memoryChart',ms,'memory_gib');
$('validation').textContent='Validation: '+JSON.stringify(D.validation)+'. All six runs completed; no skips, trainer errors, memory-cap events or watchdog aborts. Scratch model checkpoints were removed after preserving timing, outcome, PPO and memory evidence.';
$('commands').textContent=D.raw_runs.map(r=>r.command).join('\n\n')+'\n\nInput SHA256 hashes:\n'+JSON.stringify(D.preflight.inputs,null,2);$('download').onclick=()=>{let b=new Blob([JSON.stringify(D,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='final8-benchmark-data.json';a.click();URL.revokeObjectURL(a.href)};
table('old',['Historical config','Seed','Seconds','Games/min','Decisions/s'],D.earlier_incomplete_matrix.observations.map(r=>[r.configuration,r.seed,fmt(r.total_s),fmt(r.games_per_min),fmt(r.decisions_per_s)]));$('footer').textContent='Self-contained benchmark report · generated '+D.created_utc+' · all graphs use native SVG/HTML; no matplotlib, network assets or external data dependencies.';
</script></html>'''
(R/'report.html').write_text(page)
print(str(R/'report.html'))
